from cardio_1 import a, G
# I27 — Hypertension pulmonaire et autres maladies des vaisseaux pulmonaires (P-02-Pneumologie).
# Clés absentes des autres glossaires du dépôt au 09.10.2026 (relecture différée).
a('HTP', [('H', 'Hyper'), ('T', 'Tension'), ('P', 'Pulmonaire')], 'Hypertension pulmonaire', '<p>Élévation de la pression artérielle pulmonaire moyenne au-delà de 20 mmHg au repos, mesurée par cathétérisme cardiaque droit (ESC/ERS 2022). Elle regroupe cinq groupes de causes ; l’hypertension artérielle pulmonaire n’en est que le groupe 1.</p>', 'i27-seuil20')
a('HTP-TEC', [('HTP', 'Hypertension Pulmonaire'), ('T', 'Thrombo-'), ('E', 'Embolique'), ('C', 'Chronique')], 'Hypertension pulmonaire thromboembolique chronique', '<p>Groupe 4 : obstruction des artères pulmonaires par des caillots organisés en tissu fibreux, persistante après au moins trois mois d’anticoagulation efficace. Seule forme d’hypertension pulmonaire potentiellement curable par chirurgie (endartériectomie).</p>', 'i27-scinti')
a('PAPm', [('P', 'Pression'), ('A', 'Artérielle'), ('P', 'Pulmonaire'), ('m', 'moyenne')], 'Pression artérielle pulmonaire moyenne', '<p>Pression moyenne dans l’artère pulmonaire, mesurée par cathétérisme droit. Normale 14 ± 3 mmHg ; hypertension pulmonaire au-delà de 20 mmHg au repos.</p>', 'i27-seuil20')
a('PAPO', [('P', 'Pression'), ('A', 'Artérielle'), ('P', 'Pulmonaire'), ('O', 'd’Occlusion')], 'Pression artérielle pulmonaire d’occlusion', '<p>Pression mesurée ballonnet gonflé dans une branche de l’artère pulmonaire ; elle reflète la pression de l’oreillette gauche. Au-delà de 15 mmHg, l’hypertension pulmonaire a une composante postcapillaire. Équivalent anglais : PAWP.</p>', 'i27-papo')
a('BMPR2', [('B', 'Bone'), ('M', 'Morphogenetic'), ('P', 'Protein'), ('R', 'Receptor'), ('2', 'type 2')], 'Gène du récepteur de type 2 des protéines morphogénétiques osseuses', '<p>Gène dont les variants pathogènes, transmis sur le mode autosomique dominant, sont la principale cause d’hypertension artérielle pulmonaire héritable. Risque d’environ 20 % sur la vie chez les porteurs (42 % chez la femme, 14 % chez l’homme, ESC/ERS 2022).</p>', 'i27-genetique')
a('BMP', [('B', 'Bone'), ('M', 'Morphogenetic'), ('P', 'Protein')], 'Protéine morphogénétique osseuse', '<p>Famille de facteurs de croissance de la superfamille du TGF-β. Dans la paroi artérielle pulmonaire, leur signalisation par BMPR2 freine la prolifération des cellules musculaires lisses.</p>')
a('SMAD', [('SMAD', 'contraction de « Sma » (gène du nématode) et « Mad » (Mothers against decapentaplegic, gène de la drosophile) ; non développable lettre à lettre')], 'Protéines SMAD', '<p>Protéines intracellulaires qui transmettent au noyau le signal des récepteurs de la superfamille du TGF-β. Les voies BMP et activine activent des protéines SMAD différentes, aux effets antiprolifératif et prolifératif.</p>')
a('ACVRL1', [('ACVR', 'ACtiVin Receptor (récepteur de l’activine)'), ('L', 'Like (apparenté)'), ('1', 'type 1')], 'Gène de la kinase 1 apparentée au récepteur de l’activine', '<p>Gène de la télangiectasie hémorragique héréditaire de type 2 ; certains variants causent aussi une hypertension artérielle pulmonaire. Autre nom : ALK1.</p>')
a('ENG', [('ENG', 'ENdoGline (nom du gène, non développable lettre à lettre)')], 'Gène de l’endogline', '<p>Gène codant l’endogline, corécepteur endothélial de la superfamille du TGF-β. Ses variants causent la télangiectasie hémorragique héréditaire de type 1, souvent associée à des fistules artérioveineuses pulmonaires.</p>', 'i27-fistules')
a('TBX4', [('TBX', 'T-BoX (boîte T)'), ('4', 'membre 4')], 'Gène du facteur de transcription T-box 4', '<p>Gène du développement pulmonaire. Ses variants causent un syndrome à expression variable : hypertension artérielle pulmonaire héritable de l’adulte ou de l’enfant, parfois avec anomalies du développement pulmonaire et de la rotule (7e Symposium mondial, 2024).</p>')
a('SOX17', [('SOX', 'SRY-related HMG-bOX (boîte HMG apparentée au gène SRY du chromosome Y)'), ('17', 'membre 17')], 'Gène du facteur de transcription SOX17', '<p>Gène du développement vasculaire ; ses variants sont associés à l’hypertension artérielle pulmonaire idiopathique et à celle des cardiopathies congénitales.</p>')
a('EIF2AK4', [('E', 'Eukaryotic'), ('I', 'Initiation'), ('F', 'Factor'), ('2', '2'), ('A', 'Alpha'), ('K', 'Kinase'), ('4', '4')], 'Gène de la kinase 4 du facteur d’initiation eucaryote 2 alpha', '<p>Gène dont les variants bialléliques, transmis sur le mode récessif, causent la maladie veino-occlusive pulmonaire héritable.</p>', 'i27-genetique')
a('CYP2C8', [('CYP', 'CYtochrome P450'), ('2C8', 'famille 2, sous-famille C, membre 8')], 'Cytochrome P450 2C8', '<p>Enzyme hépatique du cytochrome P450. Son inhibiteur puissant, le gemfibrozil, multiplie par 11 l’exposition au métabolite actif du sélexipag : association contre-indiquée (information professionnelle suisse Uptravi®).</p>', 'i27-d-selexipag')
a('STELLAR', [('STELLAR', 'nom d’essai, non développable lettre à lettre')], 'Essai STELLAR (2023)', '<p>Essai de phase 3 du sotatercept ajouté au traitement de fond chez 323 patients atteints d’hypertension artérielle pulmonaire en classe fonctionnelle II–III : gain de 40,8 m au test de marche à 24 semaines et réduction de 84 % du décès ou de l’aggravation clinique (N Engl J Med 2023).</p>', 'i27-sotatercept')
a('ZENITH', [('ZENITH', 'nom d’essai, non développable lettre à lettre')], 'Essai ZENITH (2025)', '<p>Essai de phase 3 du sotatercept chez 172 patients atteints d’hypertension artérielle pulmonaire à haut risque : réduction du critère décès, transplantation pulmonaire ou hospitalisation (rapport des risques 0,24 ; N Engl J Med 2025).</p>', 'i27-sotatercept')
a('AMBITION', [('AMBITION', 'nom d’essai, non développable lettre à lettre')], 'Essai AMBITION (2015)', '<p>Essai randomisé de 500 patients : la bithérapie initiale ambrisentan plus tadalafil a réduit de moitié le risque d’échec clinique par rapport aux monothérapies (N Engl J Med 2015).</p>', 'i27-combinaison')
a('SERAPHIN', [('SERAPHIN', 'nom d’essai, non développable lettre à lettre')], 'Essai SERAPHIN (2013)', '<p>Essai du macitentan dans l’hypertension artérielle pulmonaire : réduction de 45 % du critère combiné de morbidité et mortalité avec 10 mg par jour (N Engl J Med 2013).</p>', 'i27-d-are')
a('GRIPHON', [('GRIPHON', 'nom d’essai, non développable lettre à lettre')], 'Essai GRIPHON (2015)', '<p>Essai du sélexipag chez 1156 patients atteints d’hypertension artérielle pulmonaire : réduction de 40 % du critère combiné de morbidité et mortalité (N Engl J Med 2015).</p>', 'i27-d-selexipag')
a('CHEST-1', [('CHEST-1', 'nom d’essai, non développable lettre à lettre')], 'Essai CHEST-1 (2013)', '<p>Essai du riociguat dans l’hypertension pulmonaire thromboembolique chronique inopérable ou persistante après chirurgie : gain de 46 m au test de marche à 16 semaines et baisse des résistances vasculaires pulmonaires (N Engl J Med 2013).</p>', 'i27-d-riociguat')
a('PATENT-1', [('PATENT-1', 'nom d’essai, non développable lettre à lettre')], 'Essai PATENT-1 (2013)', '<p>Essai du riociguat dans l’hypertension artérielle pulmonaire : gain de 36 m au test de marche à 12 semaines (N Engl J Med 2013).</p>', 'i27-d-riociguat')
a('ARTEMIS', [('ARTEMIS', 'nom d’essai, non développable lettre à lettre')], 'Essai ARTEMIS-IPF (ambrisentan)', '<p>Essai de l’ambrisentan dans la fibrose pulmonaire idiopathique : risque accru de progression et d’hospitalisations respiratoires, d’où la contre-indication de l’ambrisentan dans cette maladie (7e Symposium mondial, 2024).</p>', 'i27-groupe3')
a('RISE-IIP', [('RISE', 'nom d’essai, non développable lettre à lettre'), ('IIP', 'Idiopathic Interstitial Pneumonia (pneumopathie interstitielle idiopathique)')], 'Essai RISE-IIP (riociguat)', '<p>Essai du riociguat dans l’hypertension pulmonaire des pneumopathies interstitielles idiopathiques, arrêté précocement pour un signal d’excès de mortalité (7e Symposium mondial, 2024).</p>', 'i27-groupe3')
a('INCREASE', [('INCREASE', 'nom d’essai, non développable lettre à lettre')], 'Essai INCREASE (tréprostinil inhalé)', '<p>Essai randomisé de 16 semaines du tréprostinil inhalé dans l’hypertension pulmonaire des pneumopathies interstitielles (PAPm ≥ 25 mmHg, RVP &gt; 3 unités Wood) : gain à la marche de six minutes et moins d’aggravations cliniques (7e Symposium mondial, 2024).</p>', 'i27-groupe3')
a('PERFECT', [('PERFECT', 'nom d’essai, non développable lettre à lettre')], 'Essai PERFECT (tréprostinil inhalé dans la BPCO)', '<p>Essai du tréprostinil inhalé dans l’hypertension pulmonaire de la BPCO, arrêté précocement pour excès d’effets indésirables graves et suspicion de surmortalité (7e Symposium mondial, 2024).</p>', 'i27-groupe3')
a('COMPERA', [('COMPERA', 'COMparative, Prospective Registry of newly initiated therapies for pulmonary hypertension ; acronyme non développable lettre à lettre')], 'Registre européen COMPERA', '<p>Registre prospectif européen des patients atteints d’hypertension pulmonaire qui débutent un traitement. Il a dérivé le modèle de risque à quatre strates repris par l’ESC/ERS 2022 (Hoeper, Eur Respir J 2022).</p>', 'i27-strates4')
a('DETECT', [('DETECT', 'nom d’étude, non développable lettre à lettre')], 'Étude et algorithme DETECT', '<p>Étude internationale de 466 patients sclérodermiques à risque (maladie évoluant depuis plus de 3 ans, DLCO &lt; 60 %, capacité vitale forcée ≥ 40 %) qui a dérivé un algorithme de dépistage de l’hypertension artérielle pulmonaire en deux étapes (Coghlan, Ann Rheum Dis 2014).</p>', 'i27-depistage')
a('SwissPAR', [('Swiss', 'suisse'), ('P', 'Public'), ('A', 'Assessment'), ('R', 'Report')], 'Swiss Public Assessment Report (rapport public d’évaluation de Swissmedic)', '<p>Rapport publié par Swissmedic après une autorisation ou une extension d’indication ; il résume les données évaluées et la décision.</p>')
a('AmiKo', [('AmiKo', 'nom propre de la plateforme, non développable lettre à lettre')], 'AmiKo (plateforme de consultation des informations professionnelles suisses)', '<p>Plateforme en ligne qui republie le texte intégral des informations professionnelles approuvées par Swissmedic (AIPS) ; elle sert à lire doses, contre-indications et interactions des médicaments autorisés en Suisse.</p>')
